[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Hunger Doesn't Wait — Together We Can End It</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=Playfair+Display:wght@700;800;900&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --orange-deep: #D4540A;
    --orange-bright: #E8711A;
    --orange-light: #F59E3B;
    --red-warm: #C0392B;
    --red-deep: #922B21;
    --gold-warm: #D4A017;
    --gold-light: #F0C75E;
    --cream: #FFF8F0;
    --cream-dark: #F5E6D3;
    --dark-bg: #1A1008;
    --dark-card: #2A1A0C;
    --dark-card-border: #3D2A16;
    --text-light: #FFF8F0;
    --text-muted: #C4A882;
    --text-gold: #F0C75E;
  }

  body {
    width: 1200px;
    min-height: 1800px;
    background: var(--dark-bg);
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    color: var(--text-light);
    overflow: hidden;
  }

  .poster {
    width: 1200px;
    min-height: 1800px;
    background: linear-gradient(180deg, #1A1008 0%, #231510 30%, #1E120B 60%, #1A1008 100%);
    position: relative;
    padding: 0;
  }

  /* Subtle texture overlay */
  .poster::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: radial-gradient(ellipse at 50% 0%, rgba(228,113,26,0.08) 0%, transparent 60%),
                radial-gradient(ellipse at 20% 80%, rgba(192,57,43,0.05) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 60%, rgba(212,165,23,0.04) 0%, transparent 50%);
    pointer-events: none;
    z-index: 0;
  }

  .poster > * { position: relative; z-index: 1; }

  /* ============ HEADER ============ */
  .header {
    padding: 64px 80px 48px;
    text-align: center;
    border-bottom: 1px solid rgba(212,165,23,0.15);
  }

  .header-tag {
    display: inline-block;
    font-family: 'Inter', sans-serif;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: var(--orange-bright);
    margin-bottom: 28px;
    padding: 8px 24px;
    border: 1px solid rgba(232,113,26,0.35);
    border-radius: 4px;
    background: rgba(232,113,26,0.06);
  }

  .title-main {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 72px;
    font-weight: 900;
    line-height: 1.08;
    color: var(--cream);
    max-width: 1000px;
    margin: 0 auto 24px;
    letter-spacing: -1px;
  }

  .title-main em {
    font-style: normal;
    color: var(--orange-bright);
    position: relative;
  }

  .title-main em::after {
    content: '';
    position: absolute;
    left: 0; bottom: 2px;
    width: 100%;
    height: 4px;
    background: var(--orange-bright);
    opacity: 0.3;
    border-radius: 2px;
  }

  .subtitle {
    font-size: 20px;
    font-weight: 400;
    color: var(--text-muted);
    max-width: 700px;
    margin: 0 auto;
    line-height: 1.6;
  }

  /* ============ CRISIS STATS ============ */
  .crisis-section {
    padding: 56px 80px;
  }

  .crisis-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 32px;
    max-width: 1040px;
    margin: 0 auto;
  }

  .crisis-card {
    background: linear-gradient(135deg, rgba(192,57,43,0.12) 0%, rgba(42,26,12,0.8) 100%);
    border: 1px solid rgba(192,57,43,0.2);
    border-radius: 16px;
    padding: 44px 40px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }

  .crisis-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, var(--red-warm), var(--orange-bright));
    border-radius: 16px 16px 0 0;
  }

  .crisis-card.primary {
    grid-column: 1 / -1;
    padding: 56px 40px;
    background: linear-gradient(135deg, rgba(192,57,43,0.18) 0%, rgba(42,26,12,0.9) 100%);
    border-color: rgba(192,57,43,0.3);
  }

  .crisis-card.primary::before {
    height: 4px;
    background: linear-gradient(90deg, var(--red-deep), var(--red-warm), var(--orange-bright));
  }

  .stat-number {
    font-family: 'Playfair Display', Georgia, serif;
    font-weight: 900;
    line-height: 1;
    margin-bottom: 12px;
  }

  .crisis-card.primary .stat-number {
    font-size: 96px;
    color: var(--cream);
    text-shadow: 0 0 60px rgba(232,113,26,0.3);
  }

  .crisis-card:not(.primary) .stat-number {
    font-size: 56px;
    color: var(--cream);
  }

  .stat-label {
    font-size: 15px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--orange-bright);
    margin-bottom: 8px;
  }

  .stat-context {
    font-size: 16px;
    color: var(--text-muted);
    line-height: 1.5;
    max-width: 380px;
    margin: 0 auto;
  }

  .crisis-card.primary .stat-context {
    font-size: 18px;
    max-width: 500px;
  }

  /* ============ DIVIDER ============ */
  .section-divider {
    width: 100%;
    padding: 0 80px;
  }

  .section-divider .line {
    width: 100%;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(212,165,23,0.25), transparent);
  }

  /* ============ IMPACT SECTION ============ */
  .impact-section {
    padding: 56px 80px;
  }

  .section-header {
    text-align: center;
    margin-bottom: 44px;
  }

  .section-label {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: var(--gold-warm);
    margin-bottom: 16px;
  }

  .section-title {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 44px;
    font-weight: 800;
    color: var(--cream);
    line-height: 1.15;
  }

  .impact-hero {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 48px;
    margin-bottom: 40px;
    padding: 40px;
    background: linear-gradient(135deg, rgba(232,113,26,0.1) 0%, rgba(42,26,12,0.6) 100%);
    border: 1px solid rgba(232,113,26,0.2);
    border-radius: 16px;
    position: relative;
    overflow: hidden;
  }

  .impact-hero::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
    background: linear-gradient(90deg, var(--orange-deep), var(--orange-bright), var(--gold-warm));
  }

  .impact-hero-stat {
    text-align: center;
    flex: 1;
  }

  .impact-hero-number {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 88px;
    font-weight: 900;
    color: var(--orange-bright);
    line-height: 1;
    text-shadow: 0 0 50px rgba(232,113,26,0.25);
  }

  .impact-hero-unit {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 40px;
    font-weight: 800;
    color: var(--gold-warm);
    margin-left: 4px;
  }

  .impact-hero-label {
    font-size: 16px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-top: 8px;
  }

  .impact-divider-v {
    width: 1px;
    height: 100px;
    background: linear-gradient(180deg, transparent, rgba(212,165,23,0.3), transparent);
  }

  .impact-metrics {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 24px;
  }

  .impact-metric-card {
    background: rgba(42,26,12,0.6);
    border: 1px solid var(--dark-card-border);
    border-radius: 12px;
    padding: 28px 24px;
    text-align: center;
  }

  .metric-icon {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 16px;
    font-size: 22px;
  }

  .metric-icon.orange { background: rgba(232,113,26,0.15); color: var(--orange-bright); }
  .metric-icon.gold { background: rgba(212,165,23,0.15); color: var(--gold-warm); }
  .metric-icon.red { background: rgba(192,57,43,0.15); color: #E74C3C; }

  .metric-value {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 36px;
    font-weight: 800;
    color: var(--cream);
    margin-bottom: 6px;
  }

  .metric-label {
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--text-muted);
  }

  /* ============ CONVERSION / CTA BRIDGE ============ */
  .conversion-section {
    padding: 40px 80px;
  }

  .conversion-banner {
    background: linear-gradient(135deg, var(--orange-deep) 0%, var(--orange-bright) 40%, var(--gold-warm) 100%);
    border-radius: 20px;
    padding: 44px 56px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 40px;
    position: relative;
    overflow: hidden;
  }

  .conversion-banner::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: radial-gradient(ellipse at 30% 50%, rgba(255,255,255,0.1) 0%, transparent 60%);
    pointer-events: none;
  }

  .conversion-equation {
    display: flex;
    align-items: center;
    gap: 24px;
  }

  .conversion-dollar {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 80px;
    font-weight: 900;
    color: var(--dark-bg);
    line-height: 1;
    text-shadow: 0 2px 10px rgba(0,0,0,0.15);
  }

  .conversion-equals {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 52px;
    font-weight: 800;
    color: rgba(26,16,8,0.6);
  }

  .conversion-meals {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 80px;
    font-weight: 900;
    color: var(--dark-bg);
    line-height: 1;
    text-shadow: 0 2px 10px rgba(0,0,0,0.15);
  }

  .conversion-meals-unit {
    font-size: 32px;
    font-weight: 700;
    color: rgba(26,16,8,0.75);
    display: block;
    margin-top: 4px;
  }

  .conversion-text {
    font-size: 18px;
    font-weight: 600;
    color: rgba(26,16,8,0.8);
    max-width: 300px;
    line-height: 1.5;
  }

  .conversion-text strong {
    color: var(--dark-bg);
    font-weight: 800;
  }

  /* ============ ACTION SECTION ============ */
  .action-section {
    padding: 56px 80px 40px;
  }

  .action-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    max-width: 1040px;
    margin: 0 auto;
  }

  .action-card {
    background: rgba(42,26,12,0.7);
    border: 1px solid var(--dark-card-border);
    border-radius: 16px;
    padding: 36px 32px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.3s;
  }

  .action-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 4px;
    height: 100%;
  }

  .action-card:nth-child(1)::before { background: var(--orange-bright); }
  .action-card:nth-child(2)::before { background: var(--red-warm); }
  .action-card:nth-child(3)::before { background: var(--gold-warm); }
  .action-card:nth-child(4)::before { background: var(--orange-light); }

  .action-icon-row {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 14px;
  }

  .action-icon {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 24px;
    flex-shrink: 0;
  }

  .action-card:nth-child(1) .action-icon { background: rgba(232,113,26,0.15); color: var(--orange-bright); }
  .action-card:nth-child(2) .action-icon { background: rgba(192,57,43,0.15); color: #E74C3C; }
  .action-card:nth-child(3) .action-icon { background: rgba(212,165,23,0.15); color: var(--gold-warm); }
  .action-card:nth-child(4) .action-icon { background: rgba(245,158,59,0.15); color: var(--orange-light); }

  .action-name {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 28px;
    font-weight: 800;
    color: var(--cream);
  }

  .action-desc {
    font-size: 15px;
    color: var(--text-muted);
    line-height: 1.65;
    padding-left: 64px;
  }

  .action-highlight {
    color: var(--orange-light);
    font-weight: 600;
  }

  /* ============ FOOTER ============ */
  .footer {
    padding: 36px 80px 56px;
    text-align: center;
    border-top: 1px solid rgba(212,165,23,0.12);
  }

  .footer-message {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 28px;
    font-weight: 800;
    color: var(--cream);
    margin-bottom: 16px;
    line-height: 1.3;
  }

  .footer-sub {
    font-size: 15px;
    color: var(--text-muted);
    line-height: 1.6;
    max-width: 650px;
    margin: 0 auto;
  }

  /* SVG icons inline */
  .icon-svg {
    width: 24px;
    height: 24px;
  }
</style>
</head>
<body>
<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="header-tag">The Hunger Crisis in America</div>
    <h1 class="title-main">Hunger Doesn't Wait&mdash;<br><em>Together We Can End It</em></h1>
    <p class="subtitle">48 million Americans face hunger, but a united network of food banks, volunteers, and advocates is fighting back with billions of meals every year.</p>
  </div>

  <!-- CRISIS STATS -->
  <div class="crisis-section">
    <div class="crisis-grid">
      <div class="crisis-card primary">
        <div class="stat-label">People Facing Hunger</div>
        <div class="stat-number">48 Million</div>
        <div class="stat-context">Americans struggle to put nutritious food on the table — including neighbors, classmates, coworkers, and community members.</div>
      </div>
      <div class="crisis-card">
        <div class="stat-label">Children Affected</div>
        <div class="stat-number">14 Million</div>
        <div class="stat-context">Children face hunger across the U.S., in every state, in urban and rural areas alike.</div>
      </div>
      <div class="crisis-card">
        <div class="stat-label">Reaches Every State</div>
        <div class="stat-number">50 + PR</div>
        <div class="stat-context">Hunger exists in every community across all 50 states and Puerto Rico.</div>
      </div>
    </div>
  </div>

  <div class="section-divider"><div class="line"></div></div>

  <!-- IMPACT SECTION -->
  <div class="impact-section">
    <div class="section-header">
      <div class="section-label">Our Collective Impact</div>
      <div class="section-title">Fighting Back With Action</div>
    </div>

    <!-- Hero stat: 5.7 billion meals -->
    <div class="impact-hero">
      <div class="impact-hero-stat">
        <div class="impact-hero-number">5.7<span class="impact-hero-unit"> Billion</span></div>
        <div class="impact-hero-label">Meals Distributed Through the Network</div>
      </div>
      <div class="impact-divider-v"></div>
      <div class="impact-hero-stat">
        <div class="impact-hero-number" style="color: var(--gold-warm);">4.3<span class="impact-hero-unit" style="color: var(--orange-light);"> Billion</span></div>
        <div class="impact-hero-label">Pounds of Good Food Rescued</div>
      </div>
    </div>

    <!-- Supporting metrics -->
    <div class="impact-metrics">
      <div class="impact-metric-card">
        <div class="metric-icon orange">
          <svg class="icon-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>
        </div>
        <div class="metric-value">200+</div>
        <div class="metric-label">Food Banks</div>
      </div>
      <div class="impact-metric-card">
        <div class="metric-icon gold">
          <svg class="icon-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
        </div>
        <div class="metric-value">60,000+</div>
        <div class="metric-label">Free Food Programs</div>
      </div>
