me {\n    font-family: 'Playfair Display', Georgia, serif;\n    font-size: 28px;\n    font-weight: 800;\n    color: var(--cream);\n  }\n\n  .action-desc {\n    font-size: 15px;\n    color: var(--text-muted);\n    line-height: 1.65;\n    padding-left: 64px;\n  }\n\n  .action-highlight {\n    color: var(--orange-light);\n    font-weight: 600;\n  }\n\n  /* ============ FOOTER ============ */\n  .footer {\n    padding: 36px 80px 56px;\n    text-align: center;\n    border-top: 1px solid rgba(212,165,23,0.12);\n  }\n\n  .footer-message {\n    font-family: 'Playfair Display', Georgia, serif;\n    font-size: 28px;\n    font-weight: 800;\n    color: var(--cream);\n    margin-bottom: 16px;\n    line-height: 1.3;\n  }\n\n  .footer-sub {\n    font-size: 15px;\n    color: var(--text-muted);\n    line-height: 1.6;\n    max-width: 650px;\n    margin: 0 auto;\n  }\n\n  /* SVG icons inline */\n  .icon-svg {\n    width: 24px;\n    height: 24px;\n  }\n</style>\n</head>\n<body>\n<div class=\"poster\">\n\n  <!-- HEADER -->\n  <div class=\"header\">\n    <div class=\"header-tag\">The Hunger Crisis in America</div>\n    <h1 class=\"title-main\">Hunger Doesn't Wait&mdash;<br><em>Together We Can End It</em></h1>\n    <p class=\"subtitle\">48 million Americans face hunger, but a united network of food banks, volunteers, and advocates is fighting back with billions of meals every year.</p>\n  </div>\n\n  <!-- CRISIS STATS -->\n  <div class=\"crisis-section\">\n    <div class=\"crisis-grid\">\n      <div class=\"crisis-card primary\">\n        <div class=\"stat-label\">People Facing Hunger</div>\n        <div class=\"stat-number\">48 Million</div>\n        <div class=\"stat-context\">Americans struggle to put nutritious food on the table — including neighbors, classmates, coworkers, and community members.</div>\n      </div>\n      <div class=\"crisis-card\">\n        <div class=\"stat-label\">Children Affected</div>\n        <div class=\"stat-number\">14 Million</div>\n        <div class=\"stat-context\">Children face hunger across the U.S., in every state, in urban and rural areas alike.</div>\n      </div>\n      <div class=\"crisis-card\">\n        <div class=\"stat-label\">Reaches Every State</div>\n        <div class=\"stat-number\">50 + PR</div>\n        <div class=\"stat-context\">Hunger exists in every community across all 50 states and Puerto Rico.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section-divider\"><div class=\"line\"></div></div>\n\n  <!-- IMPACT SECTION -->\n  <div class=\"impact-section\">\n    <div class=\"section-header\">\n      <div class=\"section-label\">Our Collective Impact</div>\n      <div class=\"section-title\">Fighting Back With Action</div>\n    </div>\n\n    <!-- Hero stat: 5.7 billion meals -->\n    <div class=\"impact-hero\">\n      <div class=\"impact-hero-stat\">\n        <div class=\"impact-hero-number\">5.7<span class=\"impact-hero-unit\"> Billion</span></div>\n        <div class=\"impact-hero-label\">Meals Distributed Through the Network</div>\n      </div>\n      <div class=\"impact-divider-v\"></div>\n      <div class=\"impact-hero-stat\">\n        <div class=\"impact-hero-number\" style=\"color: var(--gold-warm);\">4.3<span class=\"impact-hero-unit\" style=\"color: var(--orange-light);\"> Billion</span></div>\n        <div class=\"impact-hero-label\">Pounds of Good Food Rescued</div>\n      </div>\n    </div>\n\n    <!-- Supporting metrics -->\n    <div class=\"impact-metrics\">\n      <div class=\"impact-metric-card\">\n        <div class=\"metric-icon orange\">\n          <svg class=\"icon-svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"/><polyline points=\"9 22 9 12 15 12 15 22\"/></svg>\n        </div>\n        <div class=\"metric-value\">200+</div>\n        <div class=\"metric-label\">Food Banks</div>\n      </div>\n      <div class=\"impact-metric-card\">\n        <div class=\"metric-icon gold\">\n          <svg class=\"icon-svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n        </div>\n        <div class=\"metric-value\">60,000+</div>\n        <div class=\"metric-label\">Free Food Programs</div>\n      </div>\n      <div class=\"impact-metric-card\">\n        <div class=\"metric-icon red\">\n          <svg class=\"icon-svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z\"/></svg>\n        </div>\n        <div class=\"metric-value\">All 50</div>\n        <div class=\"metric-label\">States + Puerto Rico</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section-divider\"><div class=\"line\"></div></div>\n\n  <!-- CONVERSION BANNER: $1 = 10 meals -->\n  <div class=\"conversion-section\">\n    <div class=\"conversion-banner\">\n      <div class=\"conversion-equation\">\n        <div class=\"conversion-dollar\">$1</div>\n        <div class=\"conversion-equals\">=</div>\n        <div>\n          <div class=\"conversion-meals\">10</div>\n          <span class=\"conversion-meals-unit\">Meals</span>\n        </div>\n      </div>\n      <div class=\"conversion-text\">\n        Every dollar provides <strong>at least 10 meals</strong> to neighbors in need. Gifts are matched for a limited time to move fresh food to neighbors fast.\n      </div>\n    </div>\n  </div>\n\n  <!-- ACTION SECTION -->\n  <div class=\"action-section\">\n    <div class=\"section-header\">\n      <div class=\"section-label\">Take Action Now</div>\n      <div class=\"section-title\">How You Can Make a Difference</div>\n    </div>\n    <div class=\"action-grid\">\n      <!-- Donate -->\n      <div class=\"action-card\">\n        <div class=\"action-icon-row\">\n          <div class=\"action-icon\">\n            <svg class=\"icon-svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z\"/></svg>\n          </div>\n          <div class=\"action-name\">Donate</div>\n        </div>\n        <div class=\"action-desc\">Every <span class=\"action-highlight\">$1 provides at least 10 meals</span> to neighbors in need. Gifts are matched for a limited time.</div>\n      </div>\n      <!-- Advocate -->\n      <div class=\"action-card\">\n        <div class=\"action-icon-row\">\n          <div class=\"action-icon\">\n            <svg class=\"icon-svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg>\n          </div>\n          <div class=\"action-name\">Advocate</div>\n        </div>\n        <div class=\"action-desc\">Urge lawmakers to support community organizations and government programs that help neighbors facing hunger.</div>\n      </div>\n      <!-- Fundraise -->\n      <div class=\"action-card\">\n        <div class=\"action-icon-row\">\n          <div class=\"action-icon\">\n            <svg class=\"icon-svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"16\"/><line x1=\"8\" y1=\"12\" x2=\"16\" y2=\"12\"/></svg>\n          </div>\n          <div class=\"action-name\">Fundraise</div>\n        </div>\n        <div class=\"action-desc\">Inspire your community to come together and make a collective difference for families in need.</div>\n      </div>\n      <!-- Volunteer -->\n      <div class=\"action-card\">\n        <div class=\"action-icon-row\">\n          <div class=\"action-icon\">\n            <svg class=\"icon-svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n          </div>\n          <div class=\"action-name\">Volunteer</div>\n        </div>\n        <div class=\"action-desc\">Sorting, packing, and distributing food takes many hands — including yours. Join your local food bank today.</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- FOOTER -->\n  <div class=\"footer\">\n    <div class=\"footer-message\">An America Without Hunger Is Within Reach</div>\n    <div class=\"footer-sub\">When communities unite — through donations, advocacy, volunteering, and shared purpose — food rescue moves faster, and no neighbor is left behind. The resolve to end hunger is stronger than ever.</div>\n  </div>\n\n</div>\n</body>\n</html>\n", "numLines": 690, "startLine": 1, "totalLines": 690}}

